ProgressCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.sensevoice")

# SenseVoice lid_dict keys
_SENSEVOICE_LANGS = {"auto", "zh", "en", "yue", "ja", "ko", "nospeech"}

# Process-level FunASR AutoModel cache (in-process path + warm worker child).
_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()

# Long-lived SenseVoice worker (avoids Torch+FunASR reload per job).
_WARM_LOCK = threading.Lock()
_WARM_JOB_LOCK = threading.Lock()  # one in-flight warm job at a time
_WARM_PROC: subprocess.Popen | None = None
_WARM_KEY: str | None = None
_WARM_STDOUT_THREAD: threading.Thread | None = None
_WARM_PROGRESS: ProgressCb | None = None
_WARM_PROGRESS_LOCK = threading.Lock()


def clear_model_cache() -> int:
    """Drop cached AutoModel instances and kill the warm SenseVoice worker."""
    shutdown_warm_worker()
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    if n:
        try:
            import gc

            gc.collect()
        except Exception:
            pass
        try:
            import torch  # type: ignore

            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        except Exception:
            pass
    return n


def shutdown_warm_worker() -> None:
    """Terminate the persistent SenseVoice worker if running."""
    global _WARM_PROC, _WARM_KEY, _WARM_STDOUT_THREAD, _WARM_PROGRESS
    with _WARM_LOCK:
        proc = _WARM_PROC
        _WARM_PROC = None
        _WARM_KEY = None
        with _WARM_PROGRESS_LOCK:
            _WARM_PROGRESS = None
    if proc is None:
        return
    try:
        if proc.stdin:
            try:
                proc.stdin.write(b'{"op":"shutdown"}\n')
                proc.stdin.flush()
            except Exception:
                pass
    except Exception:
        pass
    try:
        from ..proc_util import kill_process_tree

        kill_process_tree(proc, reason="sensevoice_warm_shutdown")
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    try:
        proc.wait(timeout=3)
    except Exception:
        pass


def _model_cache_key(
    asr_dir: str,
    vad_dir: str | None,
    device: str,
    vad_kwargs: dict[str, Any] | None,
) -> str:
    import json as _json

    vk = ""
    if vad_kwargs:
        try:
            vk = _json.dumps(vad_kwargs, sort_keys=True, ensure_ascii=False)
        except Exception:
            vk = str(vad_kwargs)
    return f"{asr_dir}|{vad_dir or ''}|{device}|{vk}"


def _get_cached_auto_model(
    AutoModel: Any,
    *,
    asr_dir: str,
    vad_dir: str | None,
    device: str,
    vad_options: dict[str, Any] | None = None,
) -> tuple[Any, bool]:
    from ..vad import normalize_vad_options, sensevoice_vad_kwargs

    opts = normalize_vad_options(vad_options if isinstance(vad_options, dict) else {})
    vad_kw = sensevoice_vad_kwargs(opts) if vad_dir else None
    if vad_dir and not vad_kw:
        vad_kw = {"max_single_segment_time": 30000}
    key = _model_cache_key(asr_dir, vad_dir, device, vad_kw)
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached, True
    model = _load_auto_model(
        AutoModel,
        asr_dir=asr_dir,
        vad_dir=vad_dir,
        device=device,
        vad_options=vad_options,
    )
    with _MODEL_LOCK:
        _MODEL_CACHE[key] = model
    return model, False


def _clean_sensevoice_text(text: str) -> str:
    cleaned = re.sub(r"<\|[^|>]+\|>", " ", str(text or ""))
    return re.sub(r"\s+", " ", cleaned).strip()


def _map_sensevoice_language(language: str) -> str:
    raw = str(language or "auto").strip().lower()
    aliases = {
        "": "auto",
        "auto": "auto",
        "zh": "zh",
        "zh-cn": "zh",
        "zh-hans": "zh",
        "cn": "zh",
        "chinese": "zh",
        "zn": "zh",
        "en": "en",
        "eng": "en",
        "english": "en",
        "ja": "ja",
        "jp": "ja",
        "jpn": "ja",
        "japanese": "ja",
        "ko": "ko",
        "kor": "ko",
        "korean": "ko",
        "yue": "yue",
        "cantonese": "yue",
        "nospeech": "nospeech",
    }
    mapped = aliases.get(raw, raw)
    return mapped if mapped in _SENSEVOICE_LANGS else "auto"


def _resolve_device(device: str) -> str:
    want = str(device or "auto").strip().lower()
    if want == "cpu":
        return "cpu"
    try:
        import torch

        if torch.cuda.is_available():
            return "cuda:0"
    except Exception:
        pass
    return "cpu"


def _resolve_ffmpeg() -> str:
    return _resolve_ffmpeg_shared()


def _ensure_ffmpeg_on_path() -> None:
    ensure_ffmpeg_on_path()


def _is_16k_mono_wav(path: str) -> bool:
    """True when file is already mono PCM/float WAV at 16 kHz (preprocess output)."""
    try:
        with wave.open(path, "rb") as wf:
            return (
                int(wf.getnchannels()) == 1
                and int(wf.getframerate()) == 16000
                and int(wf.getsampwidth()) in (2, 3, 4)
            )
    except Exception:
        return False


def _ensure_wav_input(media_path: str) -> tuple[str, bool]:
    """
    Convert video/containers to 16 kHz mono wav when ffmpeg is available.
    SenseVoice/torchaudio often fails or mis-decodes raw mp4 without ffmpeg.

    Skips re-encode when input is already 16 kHz mono WAV (e.g. denoise/Demucs
    preprocess output). Other audio containers are left as-is for FunASR.
    """
    src = Path(media_path)
    suffix = src.suffix.lower()
    if suffix == ".wav" and _is_16k_mono_wav(str(src)):
        return str(src), False
    if suffix in {".mp3", ".flac", ".ogg", ".pcm"}:
        return str(src), False
    # Video containers, or WAV that is not already 16 kHz mono.
    ffmpeg = _resolve_ffmpeg()
    if not ffmpeg:
        return str(src), False

    fd, out = tempfile.mkstemp(prefix="transub_sv_", suffix=".wav")
    os.close(fd)
    cmd = [
        ffmpeg,
        "-y",
        "-i",
        str(src),
        "-vn",
        "-ac",
        "1",
        "-ar",
        "16000",
        "-f",
        "wav",
        out,
    ]
    try:
        run_kwargs: dict[str, Any] = {
            "capture_output": True,
            "text": True,
            "encoding": "utf-8",
            "errors": "replace",
            "check": False,
        }
        if os.name == "nt":
            run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.run(cmd, **run_kwargs)
        if proc.returncode != 0 or not Path(out).exists() or Path(out).stat().st_size < 44:
            try:
                os.remove(out)
            except OSError:
                pass
            err = (proc.stderr or proc.stdout or "").strip().splitlines()
            tail = err[-3:] if err else []
            raise RuntimeError(
                "ffmpeg 转码失败，无法从视频提取音频。"
                + (f" 详情: {' | '.join(tail)}" if tail else "")
            )
        return out, True
    except FileNotFoundError as err:
        try:
            os.remove(out)
        except OSError:
            pass
        raise RuntimeError(
            "未找到 ffmpeg。请在设置 → 环境 → FFmpeg 中配置可用路径后重试。"
        ) from err


def _wav_duration_s(wav_path: str) -> float:
    try:
        with wave.open(wav_path, "rb") as wf:
            frames = wf.getnframes()
            rate = wf.getframerate() or 16000
            return max(0.0, float(frames) / float(rate))
    except Exception:
        return 0.0


_SENTENCE_END_CHARS = set("。！？!?．.｡")
_CLAUSE_BREAK_CHARS = set("、，,;； ")
# Pause between words that usually marks a turn / breath (seconds).
_WORD_GAP_BREAK_S = 0.40
# Hard cap for a single subtitle cue (SenseVoice CTC often stretches to ~10s).
_MAX_CUE_DURATION_S = 6.0
_MAX_CJK_CHARS = 28
_MAX_LATIN_CHARS = 52


def _is_cjk_script_char(ch: str) -> bool:
    """CJK ideographs + Japanese kana (SenseVoice JP/ZH/YUE tokens)."""
    if not ch:
        return False
    o = ord(ch)
    return (
        0x4E00 <= o <= 0x9FFF  # CJK Unified
        or 0x3040 <= o <= 0x309F  # Hiragana
        or 0x30A0 <= o <= 0x30FF  # Katakana
        or 0x3400 <= o <= 0x4DBF  # CJK Ext A
        or 0xF900 <= o <= 0xFAFF  # CJK Compatibility
        or 0xFF66 <= o <= 0xFF9D  # Halfwidth katakana
    )


def _display_len(text: str) -> int:
    """Visible length ignoring ASR spacing artifacts."""
    return len(re.sub(r"\s+", "", str(text or "")))


def _is_cjk_heavy(text: str) -> bool:
    raw = re.sub(r"\s+", "", str(text or ""))
    if not raw:
        return False
    cjk = sum(1 for ch in raw if _is_cjk_script_char(ch))
    return (cjk / max(len(raw), 1)) >= 0.25


def _split_subtitle_sentences(text: str) -> list[str]:
    """Split a long ASR blob into subtitle-sized sentences."""
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [
        p.strip()
        for p in re.split(r"(?<=[。！？!?．.｡])\s*|\n+", raw)
        if p and str(p).strip()
    ]
    if not parts:
        parts = [raw]
    out: list[str] = []
    max_chars = _MAX_CJK_CHARS if _is_cjk_heavy(raw) else _MAX_LATIN_CHARS
    soft = max(12, int(max_chars * 0.7))
    for part in parts:
        if _display_len(part) <= max_chars:
            out.append(part)
            continue
        buf = ""
        for ch in part:
            buf += ch
            n = _display_len(buf)
            if n >= soft and ch in _CLAUSE_BREAK_CHARS:
                out.append(buf.strip())
                buf = ""
            elif n >= max_chars:
                out.append(buf.strip())
                buf = ""
        if buf.strip():
            out.append(buf.strip())
    return out or [raw]


def _to_seconds(value: Any, *, duration_s: float = 0.0, prefer_ms: bool = False) -> float:
    """
    Convert FunASR time values to seconds.

    SenseVoice CTC `post()` and VAD `sentence_info` typically emit milliseconds.
    Prefer duration-aware detection over a fragile absolute threshold.
    """
    try:
        t = float(value or 0)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(t) or t < 0:
        return 0.0
    if prefer_ms:
        return t / 1000.0
    # Clearly beyond media length when treated as seconds → milliseconds.
    if duration_s > 0 and t > duration_s * 1.5 + 1.0:
        return t / 1000.0
    # Absolute large values are almost always ms for ASR segments.
    if t >= 10000:
        return t / 1000.0
    return t


def _pair_to_seconds(
    start: Any,
    end: Any,
    *,
    duration_s: float = 0.0,
    prefer_ms: bool = False,
) -> tuple[float, float]:
    start_f = _to_seconds(start, duration_s=duration_s, prefer_ms=prefer_ms)
    end_f = _to_seconds(end, duration_s=duration_s, prefer_ms=prefer_ms)
    # If units still look inconsistent (one looks like ms, one like s), coerce both via max.
    if not prefer_ms and duration_s > 0:
        raw_start = float(start or 0)
        raw_end = float(end or 0)
        if max(raw_start, raw_end) > duration_s * 1.5 + 1.0:
            start_f = raw_start / 1000.0
            end_f = raw_end / 1000.0
    if end_f < start_f:
        end_f = start_f
    return start_f, end_f


def _join_word_tokens(tokens: list[str]) -> str:
    """Join SenseVoice / FunASR word tokens into display text."""
    if not tokens:
        return ""
    raw = "".join(tokens)
    # CJK / Japanese kana streams should not insert ASCII spaces between tokens.
    if _is_cjk_heavy(raw):
        return re.sub(r"\s+", "", raw).strip()
    return " ".join(t for t in tokens if t).strip()


def _sanitize_word_span(word: str, start_f: float, end_f: float) -> tuple[float, float]:
    """
    Clamp obviously broken CTC spans.

    SenseVoice often stretches the last token of a VAD/merge window to the window
    end (~10s), which makes short utterances look 10 seconds long.
    """
    if end_f < start_f:
        end_f = start_f
    n = max(_display_len(word), 1)
    punct_only = all((ch in _SENTENCE_END_CHARS or ch in _CLAUSE_BREAK_CHARS) for ch in word)
    if punct_only:
        max_dur = 0.45
    else:
        # ~0.28–0.4s per CJK mora/char with slack for emphasis.
        max_dur = max(0.55, min(2.8, n * 0.40 + 0.35))
    dur = end_f - start_f
    if dur > max_dur * 2.2:
        end_f = start_f + max_dur
    return start_f, end_f


def _estimate_cue_max_duration(text: str) -> float:
    n = max(_display_len(text), 1)
    if _is_cjk_heavy(text):
        return max(0.9, min(_MAX_CUE_DURATION_S, n * 0.38 + 0.55))
    return max(1.0, min(_MAX_CUE_DURATION_S, n * 0.12 + 0.8))


def _cues_from_word_timestamps(
    words: list[Any],
    timestamps: list[Any],
    *,
    time_offset_s: float = 0.0,
    duration_s: float = 0.0,
    fallback_text: str = "",
) -> list[dict[str, Any]]:
    """
    Group CTC word timestamps into subtitle-sized cues using real start/end times.
    FunASR SenseVoice `post()` returns timestamp pairs in milliseconds.
    """
    pairs: list[tuple[str, float, float]] = []
    n = min(len(words), len(timestamps)) if words else 0
    if n > 0:
        for i in range(n):
            word = _clean_sensevoice_text(str(words[i] or ""))
            if not word:
                continue
            ts = timestamps[i]
            if not isinstance(ts, (list, tuple)) or len(ts) < 2:
                continue
            start_f, end_f = _pair_to_seconds(
                ts[0], ts[1], duration_s=duration_s, prefer_ms=True
            )
            start_f, end_f = _sanitize_word_span(word, start_f, end_f)
            pairs.append((word, start_f, end_f))
    elif isinstance(timestamps, list) and timestamps and fallback_text:
        # Timestamp-only payload: keep one cue spanning speech, then clamp by text length.
        starts: list[float] = []
        ends: list[float] = []
        for ts in timestamps:
            if isinstance(ts, (list, tuple)) and len(ts) >= 2:
                s, e = _pair_to_seconds(ts[0], ts[1], duration_s=duration_s, prefer_ms=True)
                starts.append(s)
                ends.append(e)
        if starts and ends:
            start_f = min(starts)
            end_f = max(max(ends), start_f)
            end_f = min(end_f, start_f + _estimate_cue_max_duration(fallback_text))
            return [
                {
                    "start": start_f + time_offset_s,
                    "end": end_f + time_offset_s,
                    "text": fallback_text,
                }
            ]
        return []

    if not pairs:
        return []

    cues: list[dict[str, Any]] = []
    buf_words: list[str] = []
    cue_start = pairs[0][1]
    cue_end = pairs[0][2]
    last_content_end = pairs[0][2]

    def _flush() -> None:
        nonlocal buf_words, cue_start, cue_end, last_content_end
        text = _join_word_tokens(buf_words)
        if text:
            end_t = max(cue_end, cue_start)
            # Prefer last non-punctuation token end when the final mark was stretched.
            if last_content_end > cue_start:
                end_t = min(end_t, max(last_content_end, cue_start + 0.25))
            end_t = min(end_t, cue_start + _estimate_cue_max_duration(text))
            end_t = max(end_t, cue_start + 0.35)
            cues.append(
                {
                    "start": cue_start + time_offset_s,
                    "end": end_t + time_offset_s,
                    "text": text,
                }
            )
        buf_words = []

    max_chars = _MAX_CJK_CHARS
    # Detect script from the whole token stream once.
    if not _is_cjk_heavy(_join_word_tokens([p[0] for p in pairs])):
        max_chars = _MAX_LATIN_CHARS
    soft_chars = max(10, int(max_chars * 0.55))

    for word, start_f, end_f in pairs:
        punct_only = all(
            (ch in _SENTENCE_END_CHARS or ch in _CLAUSE_BREAK_CHARS or ch.isspace())
            for ch in word
        )
        if buf_words and start_f - cue_end >= _WORD_GAP_BREAK_S:
            _flush()
        if not buf_words:
            cue_start = start_f
            last_content_end = end_f
        buf_words.append(word)
        cue_end = max(end_f, cue_start)
        if not punct_only:
            last_content_end = max(last_content_end, end_f)
        joined = _join_word_tokens(buf_words)
        last_ch = word[-1] if word else ""
        disp = _display_len(joined)
        should_break = False
        # CJK often ends a short clause on a punctuation-only token (e.g. "你好" + "。").
        if last_ch in _SENTENCE_END_CHARS and disp >= 1:
            should_break = True
        elif disp >= soft_chars and last_ch in _CLAUSE_BREAK_CHARS:
            should_break = True
        elif disp >= max_chars:
            should_break = True
        elif (cue_end - cue_start) >= _MAX_CUE_DURATION_S and disp >= 6:
            should_break = True
        if should_break:
            _flush()

    if buf_words:
        _flush()
    return cues


def _sensevoice_score_meta(item: dict[str, Any] | None) -> dict[str, Any]:
    """Pass through backend confidence/score fields when FunASR provides them."""
    if not isinstance(item, dict):
        return {}
    meta: dict[str, Any] = {}
    for key in ("confidence", "score", "probability", "prob"):
        raw = item.get(key)
        if raw is None:
            continue
        try:
            meta[key if key != "prob" else "probability"] = float(raw)
            break
        except (TypeError, ValueError):
            continue
    return meta


def _refine_cue_timings(cues: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Final pass: clamp inflated cue ends and drop empty rows."""
    out: list[dict[str, Any]] = []
    for cue in cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        # Normalize leftover Japanese/CJK spacing from older join paths.
        if _is_cjk_heavy(text):
            text = re.sub(r"\s+", "", text)
        start = float(cue.get("start") or 0.0)
        end = float(cue.get("end") or start)
        if end <= start:
            end = start + 0.6
        max_dur = _estimate_cue_max_duration(text)
        if end - start > max_dur:
            end = start + max_dur
        row: dict[str, Any] = {"start": start, "end": end, "text": text}
        for key in ("confidence", "score", "probability", "avgLogprob", "noSpeechProb"):
            if key in cue and cue.get(key) is not None:
                row[key] = cue.get(key)
        out.append(row)
    return out


def _has_real_timestamps(cues: list[dict[str, Any]], *, duration_s: float) -> bool:
    """True when cues already carry usable audio-aligned times (not invented blobs)."""
    if not cues:
        return False
    if len(cues) >= 2:
        # Multiple distinct windows almost always come from VAD/CTC.
        starts = [float(c.get("start") or 0) for c in cues]
        ends = [float(c.get("end") or 0) for c in cues]
        if max(ends) > min(starts) + 0.05:
            return True
    cue = cues[0]
    start = float(cue.get("start") or 0.0)
    end = float(cue.get("end") or 0.0)
    span = max(0.0, end - start)
    text = str(cue.get("text") or "").strip()
    # Placeholder spans used when SenseVoice returns text only.
    if span <= 5.5 and start <= 0.05 and len(text) >= 80:
        return False
    if duration_s > 1.0 and span >= duration_s * 0.9 and len(text) >= 80:
        # Single cue covering almost the whole media — likely collapsed / invented.
        return False
    if span > 0.2 and len(text) > 0:
        return True
    return False


def _resegment_long_cues(
    cues: list[dict[str, Any]],
    *,
    duration_s: float,
) -> list[dict[str, Any]]:
    """
    Last-resort expansion when SenseVoice returns one text blob without real timestamps
    (output_timestamp=False fallback). Prefer CTC/VAD times; only invent by character weight
    when alignment is missing.
    """
    if not cues or duration_s <= 1.0:
        return cues
    if _has_real_timestamps(cues, duration_s=duration_s):
        # Still split an oversized cue that already has a real window, keeping its span.
        rebuilt: list[dict[str, Any]] = []
        for cue in cues:
            text = str(cue.get("text") or "").strip()
            start = float(cue.get("start") or 0.0)
            end = float(cue.get("end") or 0.0)
            if end <= start:
                end = start + 3.0
            if _display_len(text) < 90:
                rebuilt.append({"start": start, "end": end, "text": text})
                continue
            sentences = _split_subtitle_sentences(text)
            if len(sentences) <= 1:
                rebuilt.append({"start": start, "end": end, "text": text})
                continue
            span = end - start
            total_w = sum(max(_display_len(s), 1) for s in sentences) or 1
            t = start
            for i, sent in enumerate(sentences):
                dur = span * (_display_len(sent) / total_w)
                end_t = end if i == len(sentences) - 1 else min(end, t + max(dur, 0.4))
                rebuilt.append({"start": t, "end": max(end_t, t + 0.3), "text": sent})
                t = end_t
        return rebuilt

    # Invented timeline for collapsed no-timestamp results.
    if len(cues) == 1:
        cue = cues[0]
        text = str(cue.get("text") or "").strip()
        if _display_len(text) < 40:
            return cues
        sentences = _split_subtitle_sentences(text)
        if len(sentences) <= 1:
            return [{"start": 0.0, "end": max(duration_s, 1.0), "text": text}]
        total_w = sum(max(_display_len(s), 1) for s in sentences) or 1
        t = 0.0
        rebuilt: list[dict[str, Any]] = []
        for i, sent in enumerate(sentences):
            dur = duration_s * (_display_len(sent) / total_w)
            if i == len(sentences) - 1:
                end_t = duration_s
            else:
                end_t = min(duration_s, t + max(dur, 0.5))
            rebuilt.append({"start": t, "end": max(end_t, t + 0.4), "text": sent})
            t = end_t
        return rebuilt

    return cues


def _parse_cues_from_result(
    raw: Any,
    *,
    time_offset_s: float = 0.0,
    duration_s: float = 0.0,
) -> list[dict[str, Any]]:
    cues: list[dict[str, Any]] = []
    items = raw if isinstance(raw, list) else [raw]
    for item in items:
        if not isinstance(item, dict):
            continue
        text = _clean_sensevoice_text(str(item.get("text") or ""))
        # Prefer sentence_info when present (VAD / diarization pipeline)
        sentence_info = item.get("sentence_info") or item.get("sentence_info_list")
        if isinstance(sentence_info, list) and sentence_info:
            for sent in sentence_info:
                if not isinstance(sent, dict):
                    continue
                st = _clean_sensevoice_text(str(sent.get("text") or ""))
                words = sent.get("words")
                ts = sent.get("timestamp") or sent.get("time_stamp")
                if isinstance(words, list) and isinstance(ts, list) and words and ts:
                    part = _cues_from_word_timestamps(
                        words,
                        ts,
                        time_offset_s=time_offset_s,
                        duration_s=duration_s,
                        fallback_text=st,
                    )
                    if part:
                        cues.extend(part)
                        continue
                if not st:
                    continue
                start_f, end_f = _pair_to_seconds(
                    sent.get("start", sent.get("start_time", 0)),
                    sent.get("end", sent.get("end_time", 0)),
                    duration_s=duration_s,
                    prefer_ms=True,
                )
                if end_f <= start_f:
                    end_f = start_f + 3.0
                cues.append(
                    {
                        "start": start_f + time_offset_s,
                        "end": end_f + time_offset_s,
                        "text": st,
                        **_sensevoice_score_meta(sent),
                    }
                )
            continue

        words = item.get("words")
        ts = item.get("timestamp") or item.get("time_stamp")
        if isinstance(ts, list) and ts:
            part = _cues_from_word_timestamps(
                words if isinstance(words, list) else [],
                ts,
                time_offset_s=time_offset_s,
                duration_s=duration_s,
                fallback_text=text,
            )
            if part:
                cues.extend(part)
                continue

        if text:
            # Fallback: single block; VAD segment may carry start/end
            start_f, end_f = _pair_to_seconds(
                item.get("start", 0),
                item.get("end", 0),
                duration_s=duration_s,
            )
            if end_f <= start_f:
                end_f = start_f + 3.0
            cues.append(
                {
                    "start": start_f + time_offset_s,
                    "end": end_f + time_offset_s,
                    "text": text,
                    **_sensevoice_score_meta(item),
                }
            )

    if not cues and items:
        first = items[0]
        text = _clean_sensevoice_text(
            str(first.get("text") if isinstance(first, dict) else first)
        )
        if text:
            cues = [{"start": time_offset_s, "end": time_offset_s + 5.0, "text": text}]
    return cues


def _salvage_cues_from_raw(
    raw: Any,
    *,
    duration_s: float = 0.0,
    time_offset_s: float = 0.0,
) -> list[dict[str, Any]]:
    """Last-chance extract when structured timestamp parsing yields nothing."""
    items = raw if isinstance(raw, list) else [raw]
    texts: list[str] = []
    for item in items:
        if isinstance(item, dict):
            t = _clean_sensevoice_text(str(item.get("text") or ""))
            if t:
                texts.append(t)
        elif item is not None:
            t = _clean_sensevoice_text(str(item))
            if t:
                texts.append(t)
    if not texts:
        return []
    blob = " ".join(texts).strip()
    end = max(duration_s, 1.0) if duration_s > 0 else time_offset_s + 5.0
    return [{"start": time_offset_s, "end": end, "text": blob}]


def _is_index_bug(err: BaseException) -> bool:
    msg = str(err).lower()
    return (
        isinstance(err, IndexError)
        or "index out of range" in msg
        or "index out of bounds" in msg
        or "device-side assert" in msg
    )


def _friendly_index_error(err: BaseException) -> str:
    return (
        "SenseVoice 推理越界（index out of range）。"
        "常见原因：视频未正确解码为音频、CUDA/VAD 分段异常。"
        "已自动尝试：更稳妥 VAD、无 VAD 分片、必要时强制 CPU。"
        "若仍失败请确认 FFmpeg 可用，或改用 Whisper 档位。"
        f" 详情: {err}"
    )


def _friendly_os_error(err: BaseException, *, phase: str) -> str:
    msg = str(err)
    win2 = getattr(err, "winerror", None) == 2 or "WinError 2" in msg or "[Errno 2]" in msg
    if win2:
        return (
            "系统找不到指定的文件。"
            "常见原因：1) 未配置可用的 ffmpeg（设置 → 环境 → FFmpeg）；"
            "2) VAD/ASR 模型下载不完整（例如 fsmn-vad 缺少 model.pt，请重新下载模型）。"
            f" 阶段={phase} 详情={msg}"
        )
    return f"SenseVoice {phase} failed: {msg}"


def _reset_cuda() -> None:
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def _sensevoice_rtf_guess(device: str) -> float:
    """
    SenseVoice-small is much faster than real-time.
    Prior CPU guess 0.28 + 3600s wall cap made 2h media look ~16% done when finished.
    """
    if str(device or "").strip().lower().startswith("cuda"):
        return 0.025
    return 0.08


def _sensevoice_expected_wall_s(duration_s: float, device: str) -> float:
    duration = max(0.0, float(duration_s or 0))
    rtf = _sensevoice_rtf_guess(device)
    if duration <= 0:
        return 90.0
    # Warmup + length-proportional; no low 3600 cap that stalls long-media timeline.
    return max(12.0, duration * rtf + 8.0)


def _run_with_progress_heartbeat(
    fn: Callable[[], Any],
    on_progress: ProgressCb | None,
    *,
    stage: str = "transcribe",
    start_pct: int = 15,
    end_pct: int = 90,
    interval_s: float = 1.2,
    detail_prefix: str = "转写中",
    duration_s: float = 0.0,
    device: str = "cpu",
) -> Any:
    """
    SenseVoice model.generate() is blocking with no native progress.
    Emit duration-aware heartbeats (processed ≈ elapsed / expected_rtf).
    """
    if not on_progress:
        return fn()

    stop = threading.Event()
    started = time.time()
    duration = max(0.0, float(duration_s or 0))
    expected_wall = _sensevoice_expected_wall_s(duration, device)

    def _emit(*, elapsed: float, finishing: bool = False) -> None:
        from ..progress import format_mmss

        if duration > 0:
            if finishing:
                ratio = 1.0
                processed = duration
            else:
                # Linear toward ~92%, then ease so overtime jobs still creep up.
                linear = elapsed / max(expected_wall, 1.0)
                if linear <= 0.92:
                    ratio = linear
                else:
                    # After expected wall: approach 0.97 asymptotically.
                    over = linear - 0.92
                    ratio = 0.92 + 0.05 * (1.0 - math.exp(-over * 2.5))
                ratio = min(0.97, max(0.0, ratio))
                processed = duration * ratio
            local = start_pct + (end_pct - start_pct) * (1.0 if finishing else ratio)
            detail = f"{detail_prefix}… {format_mmss(processed)} / {format_mmss(duration)}"
            processed_out = processed
        else:
            if finishing:
                ratio = 1.0
            else:
                ratio = 1.0 - math.exp(-elapsed / max(expected_wall * 0.85, 30.0))
                ratio = min(0.97, ratio)
            local = start_pct + (end_pct - start_pct) * (1.0 if finishing else ratio)
            mins = int(elapsed // 60)
            secs = int(elapsed % 60)
            detail = f"{detail_prefix}… {mins}:{secs:02d}"
            processed_out = elapsed
        on_progress(
            {
                "stage": stage,
                "percent": int(max(start_pct, min(end_pct, local))),
                "detail": detail,
                "processedSec": processed_out,
                "mediaDurationSec": duration if duration > 0 else None,
            }
        )

    def _tick() -> None:
        while not stop.wait(interval_s):
            _emit(elapsed=max(0.0, time.time() - started), finishing=False)

    thread = threading.Thread(target=_tick, name="sensevoice-progress", daemon=True)
    thread.start()
    try:
        _emit(elapsed=0.0, finishing=False)
        result = fn()
        # Snap timeline to full media length so logs don't end at e.g. 19:36 / 123:55.
        _emit(elapsed=max(0.0, time.time() - started), finishing=True)
        return result
    finally:
        stop.set()
        thread.join(timeout=2.0)


def _load_auto_model(
    AutoModel: Any,
    *,
    asr_dir: str,
    vad_dir: str | None,
    device: str,
    vad_options: dict[str, Any] | None = None,
):
    kwargs: dict[str, Any] = {
        "model": asr_dir,
        "device": device,
        "disable_update": True,
    }
    if vad_dir:
        from ..vad import normalize_vad_options, sensevoice_vad_kwargs

        opts = normalize_vad_options(vad_options if isinstance(vad_options, dict) else {})
        kwargs["vad_model"] = vad_dir
        kwargs["vad_kwargs"] = sensevoice_vad_kwargs(opts) or {"max_single_segment_time": 30000}
    return AutoModel(**kwargs)


def _generate_kwargs(
    wav_path: str,
    lang: str,
    extra: dict[str, Any] | None = None,
    *,
    merge_length_s: float = 8.0,
) -> dict[str, Any]:
    kwargs: dict[str, Any] = {
        "input": wav_path,
        "cache": {},
        "language": lang,
        "use_itn": True,
        "batch_size_s": 60,
        "merge_vad": True,
        # Shorter merges when UI asks for aggressive / film slicing.
        "merge_length_s": float(merge_length_s),
        # CTC word timestamps for audio-aligned cues (FunASR SenseVoice).
        "output_timestamp": True,
        # Keep engine latest.log readable (no tqdm spam).
        "disable_pbar": True,
    }
    if extra:
        kwargs.update(extra)
    return kwargs


def _transcribe_chunked_no_vad(
    model: Any,
    *,
    wav_path: str,
    lang: str,
    on_progress: ProgressCb | None,
    chunk_s: float = 25.0,
) -> list[dict[str, Any]]:
    """
    Bypass FunASR VAD entirely: cut wav into fixed windows and ASR each.
    Survives CUDA/VAD index bugs that poison a single long-form generate().
    """
    duration = _wav_duration_s(wav_path)
    if duration <= 0:
        raise RuntimeError("无法读取音频时长，ffmpeg 提取的 wav 可能无效。")

    cues: list[dict[str, Any]] = []
    total_chunks = max(1, int(math.ceil(duration / chunk_s)))
    for idx in range(total_chunks):
        start_s = idx * chunk_s
        end_s = min(duration, start_s + chunk_s)
        if end_s - start_s < 0.35:
            continue
        if on_progress:
            from ..progress import asr_local_from_timeline, format_mmss

            local = asr_local_from_timeline(processed_s=start_s, duration_s=duration, start=18.0, end=90.0)
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": int(local),
                    "detail": (
                        f"分片转写 {idx + 1}/{total_chunks} · "
                        f"{format_mmss(start_s)} / {format_mmss(duration)}"
                    ),
                    "processedSec": start_s,
                    "mediaDurationSec": duration,
                }
            )

        fd, chunk_path = tempfile.mkstemp(prefix="transub_sv_chunk_", suffix=".wav")
        os.close(fd)
        try:
            ffmpeg = _resolve_ffmpeg()
            if ffmpeg:
                cmd = [
                    ffmpeg,
                    "-y",
                    "-ss",
                    f"{start_s:.3f}",
                    "-t",
                    f"{max(0.2, end_s - start_s):.3f}",
                    "-i",
                    wav_path,
                    "-ac",
                    "1",
                    "-ar",
                    "16000",
                    "-f",
                    "wav",
                    chunk_path,
                ]
                run_kwargs: dict[str, Any] = {
                    "capture_output": True,
                    "text": True,
                    "encoding": "utf-8",
                    "errors": "replace",
                    "check": False,
                }
                if os.name == "nt":
                    run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
                proc = subprocess.run(cmd, **run_kwargs)
                if proc.returncode != 0 or Path(chunk_path).stat().st_size < 44:
                    continue
            else:
                # Fallback: copy whole file only for short audio
                if total_chunks == 1:
                    chunk_path = wav_path
                else:
                    raise RuntimeError("无 VAD 分片需要 ffmpeg，请在设置中配置 FFmpeg。")

            chunk_dur = max(0.2, end_s - start_s)
            try:
                raw = model.generate(
                    **_generate_kwargs(
                        chunk_path,
                        lang,
                        {
                            "merge_vad": False,
                            "batch_size_s": 30,
                            "output_timestamp": True,
                        },
                    )
                )
            except Exception as chunk_err:
                if not _is_index_bug(chunk_err):
                    raise
                _log.warning(
                    "SenseVoice chunk timestamp failed at %.1fs: %s; retry without timestamps",
                    start_s,
                    chunk_err,
                )
                raw = model.generate(
                    **_generate_kwargs(
                        chunk_path,
                        lang,
                        {
                            "merge_vad": False,
                            "batch_size_s": 30,
                            "output_timestamp": False,
                        },
                    )
                )
            part = _parse_cues_from_result(
                raw, time_offset_s=start_s, duration_s=chunk_dur
            )
            if not part:
                # One blob covering the window when SenseVoice returns text only
                text = ""
                if isinstance(raw, list) and raw and isinstance(raw[0], dict):
                    text = _clean_sensevoice_text(str(raw[0].get("text") or ""))
                if text:
                    part = [{"start": start_s, "end": end_s, "text": text}]
            # Clamp cues to this window (offsets already applied).
            for c in part:
                if c["end"] <= c["start"]:
                    c["end"] = end_s
                if c["start"] < start_s:
                    c["start"] = start_s
                if c["end"] > end_s + 0.5:
                    c["end"] = end_s
            cues.extend(part)
        finally:
            if chunk_path != wav_path:
                try:
                    os.remove(chunk_path)
                except OSError:
                    pass

    return cues


def sensevoice_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "sensevoice-small",
    vad_model: str = "fsmn-vad",
    vad_options: dict[str, Any] | None = None,
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
    register_subprocess: Callable[[Any], None] | None = None,
    force_inprocess: bool = False,
) -> list[dict[str, Any]]:
    """
    Transcribe with SenseVoice.

    When ``should_cancel`` is provided (job path) and ``force_inprocess`` is False,
    inference runs in a child process so cancel can ``taskkill`` the FunASR generate.
    """
    try:
        from ..runtime_extras import ensure_asr_sensevoice

        ensured = ensure_asr_sensevoice()
        if not ensured.get("ok") and not ensured.get("skipped"):
            raise RuntimeError(
                ensured.get("message")
                or "SenseVoice 运行库未就绪（需 torch / funasr / numba / scipy 等，下载 SenseVoice 时会自动安装）"
            )
    except RuntimeError:
        raise
    except Exception:
        # Best-effort; ImportError below still surfaces a clear message.
        pass
    use_sub = (
        not force_inprocess
        and should_cancel is not None
        and str(__import__("os").environ.get("TRANSUB_SENSEVOICE_INPROCESS", "")).strip()
        not in ("1", "true", "TRUE", "yes", "YES")
    )
    if use_sub:
        return _sensevoice_transcribe_subprocess(
            media_path=media_path,
            language=language,
            asr_model=asr_model,
            vad_model=vad_model,
            vad_options=vad_options,
            device=device,
            on_progress=on_progress,
            should_cancel=should_cancel,
            register_subprocess=register_subprocess,
        )
    return _sensevoice_transcribe_inprocess(
        media_path=media_path,
        language=language,
        asr_model=asr_model,
        vad_model=vad_model,
        vad_options=vad_options,
        device=device,
        on_progress=on_progress,
    )


def _sensevoice_transcribe_subprocess(
    *,
    media_path: str,
    language: str,
    asr_model: str,
    vad_model: str,
    vad_options: dict[str, Any] | None,
    device: str,
    on_progress: ProgressCb | None,
    should_cancel: Callable[[], bool] | None,
    register_subprocess: Callable[[Any], None] | None,
) -> list[dict[str, Any]]:
    """Run SenseVoice in a warm child process (cancel via taskkill)."""
    import sys
    import tempfile

    from ..proc_util import kill_process_tree

    global _WARM_PROC, _WARM_KEY, _WARM_STDOUT_THREAD, _WARM_PROGRESS

    warm_key = f"{asr_model}|{vad_model}|{device}"
    work = Path(tempfile.mkdtemp(prefix="transub_sv_job_"))
    req_path = work / "request.json"
    out_path = work / "result.json"
    req = {
        "media_path": media_path,
        "language": language,
        "asr_model": asr_model,
        "vad_model": vad_model,
        "vad_options": vad_options if isinstance(vad_options, dict) else {},
        "device": device,
    }
    req_path.write_text(json.dumps(req, ensure_ascii=False), encoding="utf-8")

    def _spawn_warm() -> subprocess.Popen:
        cmd = [
            sys.executable,
            "-m",
            "transub_engine.asr.sensevoice_worker",
            "--serve",
        ]
        # Binary pipes + explicit UTF-8: on Chinese Windows the child may still
        # inherit cp936 for text mode even when encoding="utf-8" is requested.
        child_env = os.environ.copy()
        child_env["PYTHONIOENCODING"] = "utf-8"
        child_env["PYTHONUTF8"] = "1"
        run_kwargs: dict[str, Any] = {
            "stdin": subprocess.PIPE,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.PIPE,
            "bufsize": 0,
            "env": child_env,
        }
        if os.name == "nt":
            run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(
                subprocess, "CREATE_NEW_PROCESS_GROUP", 0
            )
        else:
            run_kwargs["start_new_session"] = True
        proc = subprocess.Popen(cmd, **run_kwargs)

        def _pump_stdout() -> None:
            try:
                assert proc.stdout is not None
                for raw in iter(proc.stdout.readline, b""):
                    if not raw:
                        break
                    line = raw.decode("utf-8", errors="replace").strip()
                    if not line:
                        continue
                    try:
                        ev = json.loads(line)
                    except Exception:
                        continue
                    if not isinstance(ev, dict):
                        continue
                    if ev.get("type") == "job_done":
                        # Signal handled by waiter via result file + marker.
                        marker = ev.get("marker")
                        if marker:
                            try:
                                Path(str(marker)).write_text("1", encoding="utf-8")
                            except Exception:
                                pass
                        continue
                    with _WARM_PROGRESS_LOCK:
                        cb = _WARM_PROGRESS
                    if cb and ev.get("type") != "ready":
                        try:
                            cb({k: v for k, v in ev.items() if k != "type"} or ev)
                        except Exception:
                            pass
            except Exception:
                pass

        thread = threading.Thread(target=_pump_stdout, daemon=True)
        thread.start()
        return proc

    cancelled = False
    # Serialize warm-worker jobs (stdin protocol is single-flight).
    with _WARM_JOB_LOCK:
        try:
            with _WARM_LOCK:
                proc = _WARM_PROC
                if proc is not None and (proc.poll() is not None or _WARM_KEY != warm_key):
                    # Stale or model/device mismatch — recycle.
                    try:
                        kill_process_tree(proc, reason="sensevoice_warm_recycle")
                    except Exception:
                        pass
                    _WARM_PROC = None
                    _WARM_KEY = None
                    proc = None
                if proc is None:
                    if on_progress:
                        on_progress(
                            {
                                "stage": "model",
                                "percent": 4,
                                "detail": "SenseVoice 暖进程启动…",
                            }
                        )
                    proc = _spawn_warm()
                    _WARM_PROC = proc
                    _WARM_KEY = warm_key
                else:
                    if on_progress:
                        on_progress(
                            {
                                "stage": "model",
                                "percent": 4,
                                "detail": "SenseVoice 暖进程 · 已缓存",
                            }
                        )
                with _WARM_PROGRESS_LOCK:
                    _WARM_PROGRESS = on_progress
                if register_subprocess:
                    try:
                        register_subprocess(proc)
                    except Exception:
                        pass
                assert proc.stdin is not None
                marker = work / "done.marker"
                try:
                    if marker.exists():
                        marker.unlink()
                except OSError:
                    pass
                cmd_line = json.dumps(
                    {
                        "op": "run",
                        "request": str(req_path),
                        "output": str(out_path),
                        "marker": str(marker),
                    },
                    ensure_ascii=False,
                )
                payload = (cmd_line + "\n").encode("utf-8")
                proc.stdin.write(payload)
                proc.stdin.flush()

            # Wait for marker / result / cancel / process death.
            while True:
                if should_cancel and should_cancel():
                    cancelled = True
                    with _WARM_LOCK:
                        if _WARM_PROC is proc:
                            _WARM_PROC = None
                            _WARM_KEY = None
                    kill_process_tree(proc, reason="sensevoice_cancel")
                    break
                if marker.is_file() or out_path.is_file():
                    # Prefer marker; allow brief settle for result JSON flush.
                    if out_path.is_file():
                        try:
                            payload = json.loads(out_path.read_text(encoding="utf-8"))
                            if isinstance(payload, dict) and "ok" in payload:
                                break
                        except Exception:
                            pass
                    if marker.is_file() and out_path.is_file():
                        break
                if proc.poll() is not None:
                    break
                time.sleep(0.05)

            if cancelled or (should_cancel and should_cancel()):
                raise RuntimeError("cancelled")

            if not out_path.is_file():
                err = ""
                try:
                    if proc.stderr:
                        raw_err = proc.stderr.read() or b""
                        err = raw_err.decode("utf-8", errors="replace")[:800]
                except Exception:
                    pass
                with _WARM_LOCK:
                    if _WARM_PROC is proc:
                        _WARM_PROC = None
                        _WARM_KEY = None
                raise RuntimeError(
                    f"SenseVoice worker produced no result"
                    + (f": {err}" if err else "")
                )

            payload = json.loads(out_path.read_text(encoding="utf-8"))
            if not payload.get("ok"):
                raise RuntimeError(str(payload.get("error") or "SenseVoice worker failed"))
            cues = payload.get("cues")
            if not isinstance(cues, list):
                raise RuntimeError("SenseVoice worker returned invalid cues")
            return cues
        finally:
            with _WARM_PROGRESS_LOCK:
                if _WARM_PROGRESS is on_progress:
                    _WARM_PROGRESS = None
            try:
                import shutil

                shutil.rmtree(work, ignore_errors=True)
            except Exception:
                pass


def _sensevoice_transcribe_inprocess(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "sensevoice-small",
    vad_model: str = "fsmn-vad",
    vad_options: dict[str, Any] | None = None,
    device: str = "auto",
    on_progress: ProgressCb | None = None,
) -> list[dict[str, Any]]:
    try:
        from funasr import AutoModel  # type: ignore
    except ImportError as err:
        raise RuntimeError(
            "SenseVoice requires funasr. Install with: pip install 'transub-engine[asr-sensevoice]'"
        ) from err

    if not is_model_installed(asr_model):
        raise RuntimeError(f"ASR model not installed: {asr_model}. Run models download first.")

    # WhisperSeg / Silero are faster-whisper paths — FunASR AutoModel cannot load them.
    vad_id = str(vad_model or "").strip()
    vad_l = vad_id.lower()
    if vad_l in ("whisperseg-asmr", "whisperseg", "whisper-seg") or "whisperseg" in vad_l:
        if on_progress:
            on_progress(
                {
                    "stage": "vad",
                    "percent": 4,
                    "detail": "SenseVoice 不支持 WhisperSeg · 回退 fsmn-vad",
                }
            )
        vad_id = "fsmn-vad"
        vad_model = vad_id
    elif vad_l in ("silero-vad", "silero") or vad_l.startswith("silero"):
        if on_progress:
            on_progress(
                {
                    "stage": "vad",
                    "percent": 4,
                    "detail": "SenseVoice 不支持 Silero VAD · 回退 fsmn-vad",
                }
            )
        vad_id = "fsmn-vad"
        vad_model = vad_id

    if vad_model and not is_model_installed(vad_model):
        raise RuntimeError(
            f"VAD model not installed or incomplete: {vad_model}。"
            "请在设置中重新「下载所需模型」（需包含 model.pt）。"
        )

    asr_dir = str(model_local_path(asr_model))
    vad_dir = str(model_local_path(vad_model)) if is_model_installed(vad_model) else None
    # Allow disabling VAD via options
    if isinstance(vad_options, dict) and vad_options.get("enabled") is False:
        vad_dir = None
    dev = _resolve_device(device)
    lang = _map_sensevoice_language(language)
    cues: list[dict[str, Any]] | None = None
    wav_path = ""
    is_temp = False
    duration_s = 0.0
    _ensure_ffmpeg_on_path()

    try:
        try:
            model, was_cached = _get_cached_auto_model(
                AutoModel,
                asr_dir=asr_dir,
                vad_dir=vad_dir,
                device=dev,
                vad_options=vad_options,
            )
        except OSError as err:
            raise RuntimeError(_friendly_os_error(err, phase="load")) from err

        if on_progress:
            detail = f"加载 SenseVoice（{dev}）"
            if was_cached:
                detail += " · 已缓存"
            on_progress({"stage": "model", "percent": 5, "detail": detail})

        wav_path, is_temp = _ensure_wav_input(media_path)
        duration_s = _wav_duration_s(wav_path)
        if on_progress:
            from ..progress import format_mmss

            detail = "已用 ffmpeg 提取音频" if is_temp else "准备音频"
            if duration_s > 0:
                detail = f"{detail} · {format_mmss(duration_s)}"
            on_progress(
                {
                    "stage": "vad",
                    "percent": 15 if is_temp else 12,
                    "detail": detail,
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )
        elif not is_temp and Path(media_path).suffix.lower() not in {".wav", ".mp3", ".flac", ".ogg", ".pcm"}:
            # Video path without ffmpeg — FunASR will likely mis-decode
            if not _resolve_ffmpeg():
                raise RuntimeError(
                    "未找到 ffmpeg，无法从视频提取音频。"
                    "请在设置 → 环境 → FFmpeg 中配置可用路径后重试。"
                )

        from ..vad import normalize_vad_options, sensevoice_merge_length_s

        vad_opts_norm = normalize_vad_options(
            vad_options if isinstance(vad_options, dict) else {}
        )
        merge_len = sensevoice_merge_length_s(vad_opts_norm)

        def _generate(extra: dict[str, Any] | None = None) -> Any:
            return model.generate(
                **_generate_kwargs(wav_path, lang, extra, merge_length_s=merge_len)
            )

        if on_progress:
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 18,
                    "detail": f"开始转写（{lang}）",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )

        try:
            raw = _run_with_progress_heartbeat(
                _generate,
                on_progress,
                stage="transcribe",
                start_pct=20,
                end_pct=90,
                detail_prefix=f"转写中（{lang}）",
                duration_s=duration_s,
                device=dev,
            )
            cues = _parse_cues_from_result(raw, duration_s=duration_s)
            if not cues:
                cues = _salvage_cues_from_raw(raw, duration_s=duration_s)
        except Exception as err:
            if not _is_index_bug(err):
                raise
            _log.warning("SenseVoice primary generate failed: %s", err)

            # Retry 1: safer VAD + disable timestamps (avoids FunASR index bugs)
            if on_progress:
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": 22,
                        "detail": "换用更稳妥 VAD 参数重试…",
                        "mediaDurationSec": duration_s if duration_s > 0 else None,
                    }
                )
            try:
                raw = _run_with_progress_heartbeat(
                    lambda: _generate(
                        {
                            "merge_vad": False,
                            "batch_size_s": 30,
                            "output_timestamp": False,
                        }
                    ),
                    on_progress,
                    stage="transcribe",
                    start_pct=25,
                    end_pct=90,
                    detail_prefix=f"转写重试（{lang}）",
                    duration_s=duration_s,
                    device=dev,
                )
                cues = _parse_cues_from_result(raw, duration_s=duration_s)
            except Exception as err2:
                _log.warning("SenseVoice VAD-safe retry failed: %s", err2)
                # CUDA device-side assert often poisons the context; rebuild on CPU, no VAD.
                _reset_cuda()
                fallback_dev = "cpu"
                if on_progress:
                    on_progress(
                        {
                            "stage": "model",
                            "percent": 28,
                            "detail": f"重建模型无 VAD（{fallback_dev}）并分片重试…",
                        }
                    )
                try:
                    model = _load_auto_model(
                        AutoModel,
                        asr_dir=asr_dir,
                        vad_dir=None,
                        device=fallback_dev,
                        vad_options=None,
                    )
                    # Chunked path reports real timeline progress itself.
                    cues = _transcribe_chunked_no_vad(
                        model,
                        wav_path=wav_path,
                        lang=lang,
                        on_progress=on_progress,
                    )
                except Exception as err3:
                    _log.exception("SenseVoice chunked no-VAD fallback failed")
                    raise RuntimeError(_friendly_index_error(err3)) from err3

    except OSError as err:
        raise RuntimeError(_friendly_os_error(err, phase="generate")) from err
    except FileNotFoundError as err:
        raise RuntimeError(_friendly_os_error(err, phase="generate")) from err
    finally:
        if is_temp and wav_path:
            try:
                os.remove(wav_path)
            except OSError:
                pass

    if cues is None:
        raise RuntimeError(_friendly_index_error(RuntimeError("no result")))

    if on_progress:
        on_progress({"stage": "transcribe", "percent": 92, "detail": "整理字幕结果…"})
    cues = _resegment_long_cues(cues, duration_s=duration_s)
    cues = _refine_cue_timings(cues)
    if not cues:
        raise RuntimeError(
            "SenseVoice 未识别到有效字幕（结果为空）。"
            "可尝试：关闭影视人声分离/激进切分后重试，确认语言为日语或自动，"
            "或改用 Whisper 档位。"
        )
    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cues)} 条",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return cues
